"""Canonical body management controls, reparenting and Paste in a local profile."""
import json


def run_body_actions_checks(*, cdp, evaluate, check, wait_for, add, shot):
    root=add('Management');source=add('Original parent',root);destination=add('Destination',root)
    owner=add('Managed body',source);child=add('Descendant',owner);other=add('Copied body',source)
    wait_for('physics.settled');evaluate('physics.pause()')
    q=json.dumps
    full=['Rename','Move to…','Add to Constellation','Copy','Duplicate structure','Delete item']
    check(evaluate("!/(Add existing item|Link existing item|Portal|Your Passport|Pick:)/i.test(document.getElementById('help-dialog').textContent)&&document.getElementById('help-dialog').textContent.includes('Choose Copy, then Paste where you want an independent copy.')"), 'Help teaches independent Paste without linked-item creation or mode choices')
    check(evaluate("(()=>{const text=[...document.querySelectorAll('#help-dialog details')].find(d=>d.querySelector('summary').textContent==='Constellations').textContent;return ['Universe = where something lives','Constellation = things you want to see together','recipe from Food','workout from Fitness','city from Travel','playlist from Music','original hierarchy location','one or more Constellations','same item'].every(s=>text.includes(s));})()"), 'approved cross-category Constellation Help and shared-original mental model remain intact')

    def labels():
        return evaluate("[...contextMenu.querySelectorAll(':scope > button:not([hidden])')].map(b=>b.textContent)")

    def tap(selector):
        evaluate(f'document.querySelector({q(selector)}).scrollIntoView({{block:"nearest"}});new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
        p=evaluate(f"(()=>{{const n=document.querySelector({q(selector)}),r=n.getBoundingClientRect();return {{x:r.x+r.width/2,y:r.y+r.height/2}};}})()")
        cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[p])
        cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[])

    def select(entry_id=owner):
        evaluate(f'closeContextMenu();closeContentMenus();selectEntry(entries.get({q(entry_id)}),nodes.get({q(entry_id)}),{{openInspector:false}})')

    def preview():
        evaluate('closeInspector();hierarchySidebar.setCollapsed(true)');select()
        tap('#mobile-body-more')

    def key_escape():
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Escape',code='Escape',windowsVirtualKeyCode=27)
        cdp.call('Input.dispatchKeyEvent',type='keyUp',key='Escape',code='Escape',windowsVirtualKeyCode=27)

    for width,height in [(360,800),(390,844),(430,932),(844,390)]:
        tag=f'{width}x{height}'
        cdp.call('Emulation.setDeviceMetricsOverride',width=width,height=height,deviceScaleFactor=2,mobile=True)
        cdp.call('Emulation.setTouchEmulationEnabled',enabled=True,maxTouchPoints=5)
        wait_for('hierarchySidebar.narrow');preview()
        check(labels()==full,'CB View opens full management directly: '+tag)
        check(evaluate("!contextMenu.querySelector('[data-action=more]')&&!contextMenu.querySelector('[data-action=create]')&&!contextMenu.querySelector('[data-action=files]')&&contextMenu.querySelector('[data-action=paste]').hidden"),'no More, add/file duplicates or empty-clipboard Paste: '+tag)
        check(evaluate(f'contextEntryId==={q(owner)}&&contextReturnFocus.id==="mobile-body-more"'),'preview management is bound to the selected body: '+tag)
        check(evaluate("contextMenu.querySelectorAll(':scope > [role=separator]:not([hidden])').length===3&&(()=>{const r=contextMenu.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.bottom<=innerHeight;})()"),'full management uses three shared separators and stays within the viewport: '+tag)
        evaluate("window.managementSurface=['backgroundColor','borderRadius','padding','boxShadow','borderColor'].map(k=>getComputedStyle(contextMenu)[k]);window.managementRow=['fontSize','padding','minHeight','color'].map(k=>getComputedStyle(contextMenu.querySelector('[data-action=edit]'))[k])")
        shot('body-actions-full-'+tag)
        key_escape()
        check(evaluate("contextMenu.hidden&&document.activeElement.id==='mobile-body-more'&&document.activeElement.ariaExpanded==='false'"),'More/Escape returns to the same preview trigger: '+tag)
        evaluate('setInspectorOpen(true)')
        tap('#entry-more-button')
        check(labels()==full and evaluate(f'contextEntryId==={q(owner)}&&contentInspector.entryId==={q(owner)}'),'Contents header directly uses the identical full menu and body: '+tag)
        check(evaluate("moreButton.ariaExpanded==='true'"),'Contents trigger remains expanded while its full menu is open: '+tag)
        check(evaluate("(()=>{const r=contextMenu.getBoundingClientRect(),b=moreButton.getBoundingClientRect();return r.bottom<=b.top||r.top>=b.bottom;})()"), 'full menu scrolls as needed without covering its Contents trigger: '+tag)
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='End',code='End',windowsVirtualKeyCode=35)
        check(evaluate("(()=>{const b=document.activeElement,r=b.getBoundingClientRect(),m=contextMenu.getBoundingClientRect();return b.dataset.action==='delete'&&r.top>=m.top&&r.bottom<=m.bottom;})()"), 'last management action remains reachable within the scrolling menu: '+tag)
        key_escape()
        check(evaluate("document.activeElement.id==='entry-more-button'"),'Contents menu retains header focus ownership: '+tag)
        tap('#entry-more-button');tap('#entry-more-button')
        check(evaluate('contextMenu.hidden&&hierarchyClipboard.roots(entries).length===0'),'a second header action tap closes without accidentally copying: '+tag)
        evaluate('closeInspector();hierarchySidebar.setCollapsed(false)')
        evaluate(f"hierarchySidebar.rows.get({q(owner)}).scrollIntoView({{block:'nearest'}})")
        tap(f'.hierarchy-row[data-entry-id="{owner}"] .tree-more')
        check(labels()==full and evaluate(f'contextEntryId==={q(owner)}&&!hierarchySidebar.collapsed'),'Menu View directly shows full management for the row body: '+tag)
        # Selection can change independently while the menu retains its identity.
        evaluate('closeContextMenu();hierarchySidebar.setCollapsed(true)');preview()
        evaluate(f'selectEntry(entries.get({q(other)}),nodes.get({q(other)}),{{openInspector:false}})')
        check(evaluate(f'contextEntryId==={q(owner)}'),'management never substitutes another selected body for its retained target: '+tag)
        evaluate('closeContextMenu()')
        evaluate(f'copyHierarchyItems([{q(other)}])');preview()
        check(labels()==full[:4]+['Paste']+full[4:] and evaluate("(()=>{const r=contextMenu.getBoundingClientRect(),b=contextReturnFocus.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight&&(r.bottom<=b.top||r.top>=b.bottom);})()"), 'conditional Paste stays edge-safe without covering its trigger: '+tag)
        shot('body-actions-paste-'+tag)
        tap('#entry-context-menu [data-action=paste]')
        check(evaluate(f'pasteDialog.open&&pasteDestination==={q(owner)}&&pasteLink.hidden'), 'conditional Paste retains its body and independent-copy-only confirmation: '+tag)
        tap('#hierarchy-paste-cancel');evaluate('hierarchyClipboard.copy(entries,[])')

    cdp.call('Emulation.setDeviceMetricsOverride',width=390,height=844,deviceScaleFactor=2,mobile=True)
    preview()
    tap('#entry-context-menu [data-action=move]')
    check(evaluate(f'dialog.open&&editingId==={q(owner)}&&document.getElementById("entry-name-field").hidden&&!document.getElementById("parent-field").hidden'),'Move to reuses the existing confirm-based parent form for the exact body')
    check(evaluate(f'!moveDestinationPicker.index.entries.has({q(owner)})&&!moveDestinationPicker.index.entries.has({q(child)})&&moveDestinationPicker.index.path({q(destination)})==="Management › Destination"'),'parent choices show full paths and exclude self and descendants')
    evaluate(f'moveDestinationPicker.select({q(destination)})')
    check(evaluate(f'entries.get({q(owner)}).parentId==={q(source)}'),'choosing a destination alone does not mutate the hierarchy')
    tap('#cancel-add-entry')
    check(evaluate(f'!dialog.open&&entries.get({q(owner)}).parentId==={q(source)}'),'Move cancellation leaves the original parent intact')
    preview();tap('#entry-context-menu [data-action=move]')
    evaluate(f'moveDestinationPicker.select({q(destination)})')
    for illegal in [owner,child]:
        evaluate(f'parentField.add(new Option("Injected illegal destination",{q(illegal)}));parentField.value={q(illegal)};form.requestSubmit()')
        check(evaluate(f'dialog.open&&!formError.hidden&&entries.get({q(owner)}).parentId==={q(source)}'),'save validation independently rejects an injected self/descendant destination: '+illegal)
    evaluate(f'moveDestinationPicker.select({q(destination)});form.requestSubmit()')
    wait_for('!dialog.open&&!formSaveBusy');evaluate('physics.pause()')
    check(evaluate(f'entries.get({q(owner)}).parentId==={q(destination)}&&entries.get({q(child)}).parentId==={q(owner)}&&portals.size===0'),'confirmed Move changes the actual parent, preserves descendants and creates no link')
    check(evaluate(f'JSON.parse(localStorage.getItem("galaxy:user-data")).entries.find(e=>e.id==={q(owner)}).parentId==={q(destination)}'),'confirmed reparenting persists through the existing repository')

    preview();tap('#entry-context-menu [data-action=constellation]')
    check(evaluate(f'!document.getElementById("constellation-memberships").hidden&&contextEntryId==={q(owner)}'),'quick Add to Constellation reuses existing membership management')
    key_escape();check(evaluate("document.activeElement.id==='mobile-body-more'"),'membership submenu retains the original body trigger')
    preview();tap('#entry-context-menu [data-action=edit]')
    check(evaluate(f'dialog.open&&editingId==={q(owner)}&&!document.getElementById("entry-name-field").hidden&&document.getElementById("parent-field").hidden'),'quick Rename opens the existing name-only form for its retained body')
    evaluate('fields[0].value="Managed body renamed";form.requestSubmit()')
    wait_for('!dialog.open&&!formSaveBusy');evaluate('physics.pause()')
    check(evaluate(f'entries.get({q(owner)}).name==="Managed body renamed"'), 'direct management Rename still saves through the existing form')
    preview();tap('#entry-context-menu [data-action=duplicate-structure]')
    check(evaluate(f'structureDialog.open&&structureSourceId==={q(owner)}'), 'direct management Duplicate structure retains its exact source')
    tap('#duplicate-structure-cancel')
    preview();tap('#entry-context-menu [data-action=delete]')
    check(evaluate(f'deleteDialog.open&&entries.has({q(owner)})'), 'Delete still requires confirmation before changing the body')
    tap('#cancel-delete-entry')
    check(evaluate(f'!deleteDialog.open&&entries.has({q(owner)})'), 'Delete cancellation preserves the body and hierarchy')

    preview();tap('#entry-context-menu [data-action=copy]')
    check(evaluate(f'hierarchyClipboard.roots(entries)[0]==={q(owner)}'), 'management Copy uses the exact menu body')
    evaluate(f'copyHierarchyItems([{q(other)}])')
    preview();evaluate('closeContextMenu()');tap('#mobile-body-add')
    check(evaluate("[...addMenu.querySelectorAll('button:not([hidden])')].map(b=>b.textContent).join('|')==='Take Photo|Photo Gallery|Add item|Add task list'"),'+ still has four quick actions with a populated clipboard')
    check(evaluate("JSON.stringify(managementSurface)===JSON.stringify(['backgroundColor','borderRadius','padding','boxShadow','borderColor'].map(k=>getComputedStyle(addMenu)[k]))&&JSON.stringify(managementRow)===JSON.stringify(['fontSize','padding','minHeight','color'].map(k=>getComputedStyle(addMenu.querySelector('[data-add=gallery]'))[k]))"),'management and Add use identical surface, typography and row treatment')
    evaluate('closeContentMenus()');preview()
    check(labels()==full[:4]+['Paste']+full[4:], 'valid clipboard exposes contextual Paste beside Copy in mobile management')
    tap('#entry-context-menu [data-action=paste]')
    check(evaluate(f'pasteDialog.open&&pasteDestination==={q(owner)}&&document.getElementById("hierarchy-paste-description").textContent.includes("Managed body")'),'relocated Paste opens the same existing confirmation for the exact destination')
    check(evaluate('pasteLink.hidden&&!pasteCopy.disabled'), 'mobile Paste offers independent copies without a linked-item creation choice')
    tap('#hierarchy-paste-cancel')
    check(evaluate('!pasteDialog.open&&document.activeElement.id==="mobile-body-more"'),'Paste cancels without inserting anything and restores its body trigger')
    preview();tap('#entry-context-menu [data-action=paste]');tap('#hierarchy-paste-copy')
    wait_for('!pasteBusy&&!pasteDialog.open')
    check(evaluate(f'[...entries.values()].some(e=>e.parentId==={q(owner)}&&e.id!=={q(other)}&&e.name==="Copied body")&&portals.size===0'), 'mobile Paste creates an independent copy through the existing repository without creating a link')
    evaluate('hierarchyClipboard.copy(entries,[])');preview()
    check(labels()==full, 'clearing the clipboard removes Paste rather than disabling it')
    evaluate(f'copyHierarchyItems([{q(other)}]);window.savedAvailability=storageAvailable;storageAvailable=false');preview()
    check(labels()==full, 'unavailable storage does not expose an unusable Paste row')
    evaluate('storageAvailable=savedAvailability;hierarchyClipboard.copy(entries,[])')

    cdp.call('Emulation.setTouchEmulationEnabled',enabled=False,maxTouchPoints=1)
    cdp.call('Emulation.setDeviceMetricsOverride',width=1440,height=1000,deviceScaleFactor=1,mobile=False)
    wait_for('!hierarchySidebar.narrow');select();evaluate('setInspectorOpen(true);moreButton.click()')
    check(labels()==['Add item','Add task list']+full and evaluate(f'contextEntryId==={q(owner)}'),'desktop Contents exposes child creation and the full canonical management menu')
    evaluate(f'openContextMenu({q(root)},300,150)')
    check(labels()==['Add item','Add task list']+full[:-1]+['Archive Galaxy','Delete item'],'full Galaxy management preserves Archive Galaxy')
    evaluate(f'copyHierarchyItems([{q(other)}]);closeContextMenu();toggleContentMenu(addMenu,moreButton,{q(owner)})')
    check(evaluate("[...addMenu.querySelectorAll('button:not([hidden])')].map(b=>b.textContent).join('|')==='Add item|Add task list|Paste|Add files|Add note|Add link'"),'desktop Add retains independent-copy Paste without linked-item creation')
    shot('desktop-add-mvp')
    evaluate("addMenu.querySelector('[data-add=paste]').click()")
    check(evaluate('pasteDialog.open&&pasteLink.hidden&&!pasteCopy.disabled&&!/Link existing|Portal/.test(pasteDialog.innerText)'), 'desktop Paste offers only the existing independent-copy confirmation after a mobile opening')
    shot('desktop-paste-mvp')
    tap('#hierarchy-paste-cancel')
    check(not cdp.errors,f'no body-management browser exceptions: {cdp.errors}')
